 int [][] center = new int[sizeH][sizeW];

 // TODO: complete method

 return center;
 }

 static int getRed(int pixel) {
 // TODO: implement method
 }

 static boolean moreRedThanBlue(int pixel) {
 // TODO: implement method
 }
}

a) Die Methode «getRed» erhält als Input den Farbwert eines beliebigen Pixels. Die Methode soll den Rot-Anteil des Pixels auslesen und mit return zurückgeben. (3 Punkte)
b) Die Methode «moreRedThanBlue» erhält als Input den Farbwert eines beliebigen Pixels. Die Methode soll «true» zurückgeben, falls der Rotanteil des Pixels höher ist als der Blauanteil. Ist dies nicht der Fall, soll die Methode «false» zurückgeben. (4 Punkte)
c) Die Methode «extractCenter» erhält als Input ein beliebiges Bild als 2D-Array. Die Methode soll einen Bildausschnitt des Input-Bildes zurückgeben. Der Bildausschnitt soll immer 200 Pixel breit und 100 Pixel hoch sein und möglichst genau aus der Mitte des Input-Bildes stammen. (7 Punkte)

tasks.solution:
a) static int getRed(int pixel) {
 return (pixel >> 16) & 0xFF;
}

b) static boolean moreRedThanBlue(int pixel) {
 int red = (pixel >> 16) & 0xFF;
 int blue = pixel & 0xFF;
 return red > blue;
}

c) static int[][] extractCenter(int [][] bild) {
 int sizeH = 100;
 int sizeW = 200;
 int startH = (bild.length - sizeH) / 2;
 int startW = (bild[0].length - sizeW) / 2;
 int [][] center = new int[sizeH][sizeW];
 for (int i = 0; i < sizeH; i++) {
 for (int j = 0; j < sizeW; j++) {
 center[i][j] = bild[startH + i][startW + j];
 }
 }
 return center;
}

